import os
import time
import hashlib
import json
import logging

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - [%(levelname)s] - %(message)s'
)

# Configuration
CONFIG_DIRS = ['/etc']           # Directories to monitor
STATE_FILE = 'file_state.json'   # Where to store the baseline hashes
SCAN_INTERVAL = 60               # Seconds between scans

def get_file_hash(filepath):
    """Calculate the SHA-256 hash of a file."""
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except (PermissionError, FileNotFoundError):
        # Skip files that require elevated permissions or disappeared during scan
        return None

def scan_directories(directories):
    """Scan directories and return a dictionary of file paths mapped to their hashes."""
    current_state = {}
    for directory in directories:
        for root, _, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                # Skip symlinks to avoid infinite loops or duplicate hashing
                if not os.path.islink(filepath):
                    file_hash = get_file_hash(filepath)
                    if file_hash:
                        current_state[filepath] = file_hash
    return current_state

def load_previous_state(state_file):
    """Load the previous state (baseline) from a JSON file."""
    if os.path.exists(state_file):
        with open(state_file, 'r') as f:
            return json.load(f)
    return {}

def save_state(state, state_file):
    """Save the current state to a JSON file."""
    with open(state_file, 'w') as f:
        json.dump(state, f, indent=4)

def compare_states(previous, current):
    """Compare previous and current states to find modifications."""
    added = set(current.keys()) - set(previous.keys())
    removed = set(previous.keys()) - set(current.keys())
    modified = {f for f in current.keys() & previous.keys() if current[f] != previous[f]}
    return added, removed, modified

def main():
    logging.info(f"Starting configuration file scanner. Monitoring: {', '.join(CONFIG_DIRS)}")
    previous_state = load_previous_state(STATE_FILE)

    if not previous_state:
        logging.info("No previous state found. Initializing baseline...")
        previous_state = scan_directories(CONFIG_DIRS)
        save_state(previous_state, STATE_FILE)
        logging.info(f"Baseline established with {len(previous_state)} files. Saving to {STATE_FILE}")

    try:
        while True:
            time.sleep(SCAN_INTERVAL)
            logging.debug("Scanning for changes...")
            current_state = scan_directories(CONFIG_DIRS)

            added, removed, modified = compare_states(previous_state, current_state)

            if added:
                for f in added:
                    logging.warning(f"File CREATED: {f}")
            if removed:
                for f in removed:
                    logging.warning(f"File DELETED: {f}")
            if modified:
                for f in modified:
                    logging.warning(f"File MODIFIED: {f}")

            if added or removed or modified:
                logging.info("Updating baseline with new changes.")
                previous_state = current_state
                save_state(previous_state, STATE_FILE)
            else:
                logging.info("Scan complete: No changes detected.")

    except KeyboardInterrupt:
        logging.info("Scanner stopped by user.")

if __name__ == "__main__":
    main()
